-- LeadFlow AI — complete database schema (GENERATED by scripts/combine-migrations.sh — do not edit by hand)
-- Run ONCE in the Supabase SQL Editor of a NEW, EMPTY project.
-- Runs in a single transaction: if anything fails, nothing is applied.
-- It also records each migration in supabase_migrations.schema_migrations, so a later
-- `supabase db push` will not try to apply them again.

begin;

-- ═════════════════════════════ 20261125000000_initial_schema.sql ═════════════════════════════
-- LeadFlow AI — initial schema
-- Tenancy model: every row belongs to a business; users access a business via business_members.

create extension if not exists pgcrypto;

-- ───────────────────────────── businesses ─────────────────────────────
create table public.businesses (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- profile (used by the AI)
  name text not null,
  industry text not null default 'home_services',
  description text not null default '',
  services jsonb not null default '[]'::jsonb,        -- [{name, price_range, description}]
  service_areas text[] not null default '{}',
  opening_hours jsonb not null default '{}'::jsonb,    -- {mon:{open:"08:00",close:"18:00",closed:false},...}
  faqs jsonb not null default '[]'::jsonb,             -- [{question, answer}]
  contact_phone text,
  contact_email text,
  website text,
  booking_link text,
  tone text not null default 'friendly',               -- friendly | professional | casual
  timezone text not null default 'Europe/Dublin',
  currency text not null default 'EUR',
  average_job_value numeric(10,2) not null default 0,

  -- AI behaviour
  ai_enabled_by_default boolean not null default true,
  custom_instructions text not null default '',        -- Pro plan
  follow_up_delays_hours integer[] not null default '{4,24,72}',
  quiet_hours_start smallint not null default 20,       -- no follow-ups from 20:00…
  quiet_hours_end smallint not null default 8,          -- …until 08:00 (business timezone)

  -- notifications
  notify_email text,
  notify_phone text,
  notify_on_hot boolean not null default true,
  notify_on_attention boolean not null default true,

  -- channels
  intake_key text not null unique default encode(gen_random_bytes(18), 'hex'),
  sms_number text unique,                              -- Twilio number assigned to this business (E.164)

  -- billing
  plan text not null default 'trial',                  -- trial | starter | growth | pro
  subscription_status text not null default 'trialing',
  trial_ends_at timestamptz not null default (now() + interval '14 days'),
  current_period_end timestamptz,
  stripe_customer_id text unique,
  stripe_subscription_id text unique,

  onboarding_completed boolean not null default false
);

create table public.business_members (
  business_id uuid not null references public.businesses(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null default 'owner',                  -- owner | member
  created_at timestamptz not null default now(),
  primary key (business_id, user_id)
);
create index on public.business_members (user_id);

-- ───────────────────────────── leads ─────────────────────────────
create table public.leads (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  name text not null,
  phone text,
  email text,
  source text not null default 'manual',               -- manual | website | facebook | instagram | google | referral | webhook | sms | other
  channel text not null default 'test',                -- sms | test
  service_requested text,
  location text,
  initial_message text,

  score smallint not null default 0 check (score between 0 and 100),
  temperature text not null default 'cold' check (temperature in ('hot','warm','cold')),
  status text not null default 'new'
    check (status in ('new','contacted','engaged','qualified','won','lost','unresponsive','opted_out')),
  ai_summary text,
  details jsonb not null default '{}'::jsonb,          -- AI-extracted facts {label: value}
  ai_paused boolean not null default false,
  needs_attention boolean not null default false,
  attention_reason text,
  estimated_value numeric(10,2),

  follow_up_step smallint not null default 0,
  next_follow_up_at timestamptz,
  last_message_at timestamptz,
  last_message_preview text,
  last_inbound_at timestamptz,
  first_response_at timestamptz,
  closed_at timestamptz
);
create index on public.leads (business_id, created_at desc);
create index on public.leads (business_id, phone);
create index on public.leads (business_id, temperature);

-- ───────────────────────────── messages ─────────────────────────────
create table public.messages (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  lead_id uuid not null references public.leads(id) on delete cascade,
  created_at timestamptz not null default now(),
  direction text not null check (direction in ('inbound','outbound')),
  sender text not null check (sender in ('lead','ai','owner','system')),
  channel text not null default 'test',
  body text not null,
  status text not null default 'sent',                 -- queued | sent | delivered | failed | received
  provider_message_id text,
  error text,
  is_follow_up boolean not null default false
);
create index on public.messages (lead_id, created_at);

-- ───────────────────────────── follow-ups ─────────────────────────────
create table public.follow_ups (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  lead_id uuid not null references public.leads(id) on delete cascade,
  created_at timestamptz not null default now(),
  step smallint not null,
  scheduled_for timestamptz not null,
  status text not null default 'pending'
    check (status in ('pending','processing','sent','cancelled','skipped','failed')),
  processed_at timestamptz,
  message_id uuid references public.messages(id) on delete set null,
  note text
);
create index on public.follow_ups (status, scheduled_for);
create index on public.follow_ups (lead_id, created_at);

-- ───────────────────────────── lead events ─────────────────────────────
create table public.lead_events (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  lead_id uuid not null references public.leads(id) on delete cascade,
  created_at timestamptz not null default now(),
  type text not null,
  data jsonb not null default '{}'::jsonb
);
create index on public.lead_events (lead_id, created_at);

-- ───────────────────────────── notifications ─────────────────────────────
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  lead_id uuid references public.leads(id) on delete cascade,
  created_at timestamptz not null default now(),
  type text not null,                                  -- hot_lead | needs_attention | limit_reached | lead_won
  title text not null,
  body text not null default '',
  read_at timestamptz
);
create index on public.notifications (business_id, created_at desc);

-- ───────────────────────────── updated_at triggers ─────────────────────────────
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
create trigger businesses_touch before update on public.businesses for each row execute function public.touch_updated_at();
create trigger leads_touch before update on public.leads for each row execute function public.touch_updated_at();

-- ───────────────────────────── row level security ─────────────────────────────
create or replace function public.is_member(bid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.business_members where business_id = bid and user_id = auth.uid());
$$;

alter table public.businesses enable row level security;
alter table public.business_members enable row level security;
alter table public.leads enable row level security;
alter table public.messages enable row level security;
alter table public.follow_ups enable row level security;
alter table public.lead_events enable row level security;
alter table public.notifications enable row level security;

create policy "members read business" on public.businesses for select using (public.is_member(id));
-- Billing columns are changed only by the server (service role) via Stripe webhooks:
create policy "members update business" on public.businesses for update using (public.is_member(id)) with check (public.is_member(id));
revoke insert, update, delete on public.businesses from authenticated, anon;
grant update (name, industry, description, services, service_areas, opening_hours, faqs, contact_phone,
  contact_email, website, booking_link, tone, timezone, currency, average_job_value, ai_enabled_by_default,
  custom_instructions, follow_up_delays_hours, quiet_hours_start, quiet_hours_end, notify_email, notify_phone,
  notify_on_hot, notify_on_attention, onboarding_completed)
  on public.businesses to authenticated;

create policy "read own memberships" on public.business_members for select using (user_id = auth.uid());

create policy "members all leads" on public.leads for all using (public.is_member(business_id)) with check (public.is_member(business_id));
create policy "members all messages" on public.messages for all using (public.is_member(business_id)) with check (public.is_member(business_id));
create policy "members read follow_ups" on public.follow_ups for select using (public.is_member(business_id));
create policy "members read events" on public.lead_events for select using (public.is_member(business_id));
create policy "members read notifications" on public.notifications for select using (public.is_member(business_id));
create policy "members update notifications" on public.notifications for update using (public.is_member(business_id));

-- Creating a business + owner membership atomically (called from onboarding).
create or replace function public.create_business(p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare bid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select business_id into bid from public.business_members where user_id = auth.uid() limit 1;
  if bid is not null then return bid; end if;
  insert into public.businesses (name, notify_email)
    values (p_name, (select email from auth.users where id = auth.uid()))
    returning id into bid;
  insert into public.business_members (business_id, user_id, role) values (bid, auth.uid(), 'owner');
  return bid;
end $$;
revoke execute on function public.create_business(text) from anon;

-- ═════════════════════════════ 20261126000000_security_hardening.sql ═════════════════════════════
-- Security & reliability hardening.
-- Additive only (new columns/tables/policies) — safe to apply to a live database.

-- ─────────────── 1. Least privilege: browser roles get read access only ───────────────
-- All writes to leads/messages/follow-ups/events go through the server (service role) after
-- an explicit authorization check. The browser can never forge a message or edit a score.

revoke all on all tables in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
revoke all on all functions in schema public from anon;
alter default privileges in schema public revoke execute on functions from anon, public;

drop policy if exists "members all leads" on public.leads;
drop policy if exists "members all messages" on public.messages;
create policy "members read leads" on public.leads for select to authenticated using (public.is_member(business_id));
create policy "members read messages" on public.messages for select to authenticated using (public.is_member(business_id));

revoke insert, update, delete, truncate on public.leads, public.messages, public.follow_ups, public.lead_events,
  public.business_members from authenticated;
revoke insert, delete, truncate on public.notifications, public.businesses from authenticated;
revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;

-- Make every policy explicit about the role it applies to.
alter policy "members read business" on public.businesses to authenticated;
alter policy "members update business" on public.businesses to authenticated;
alter policy "read own memberships" on public.business_members to authenticated;
alter policy "members read follow_ups" on public.follow_ups to authenticated;
alter policy "members read events" on public.lead_events to authenticated;
alter policy "members read notifications" on public.notifications to authenticated;
alter policy "members update notifications" on public.notifications to authenticated;

-- ─────────────── 2. Reliability columns ───────────────
alter table public.leads
  add column if not exists ai_lock_until timestamptz,          -- per-lead mutex: one AI turn at a time
  add column if not exists ai_rerun boolean not null default false, -- a message arrived while locked
  add column if not exists last_outbound_at timestamptz,
  add column if not exists ai_retry_count smallint not null default 0;

alter table public.follow_ups add column if not exists attempts smallint not null default 0;
alter table public.businesses add column if not exists stripe_event_at timestamptz; -- ignore out-of-order Stripe events

-- One stored inbound message per provider message ID → Twilio retries can't create duplicates.
create unique index if not exists messages_provider_id_unique
  on public.messages (provider_message_id) where provider_message_id is not null;
create index if not exists messages_business_sender_created on public.messages (business_id, sender, created_at);
create index if not exists leads_sweep on public.leads (status, ai_paused, last_inbound_at);

-- ─────────────── 3. Webhook idempotency ───────────────
create table if not exists public.webhook_events (
  provider text not null,
  event_id text not null,
  received_at timestamptz not null default now(),
  status text not null default 'processing',      -- processing | done | failed
  primary key (provider, event_id)
);
alter table public.webhook_events enable row level security;  -- no policies: service role only
revoke all on public.webhook_events from anon, authenticated;

-- ─────────────── 4. Rate limiting (fixed window, stored in Postgres) ───────────────
create table if not exists public.rate_limits (
  key text not null,
  window_start timestamptz not null,
  count integer not null default 0,
  primary key (key, window_start)
);
alter table public.rate_limits enable row level security;     -- no policies: service role only
revoke all on public.rate_limits from anon, authenticated;

create or replace function public.rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  ws timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  c integer;
begin
  insert into public.rate_limits (key, window_start, count) values (p_key, ws, 1)
  on conflict (key, window_start) do update set count = public.rate_limits.count + 1
  returning count into c;
  return c <= p_limit;
end $$;

-- ─────────────── 5. Per-lead AI lock (prevents duplicate / concurrent replies) ───────────────
create or replace function public.claim_lead_turn(p_lead uuid, p_seconds integer default 90)
returns boolean language plpgsql security definer set search_path = public as $$
declare ok boolean;
begin
  update public.leads set ai_lock_until = now() + make_interval(secs => p_seconds), ai_rerun = false
   where id = p_lead and (ai_lock_until is null or ai_lock_until < now())
  returning true into ok;
  if ok is null then
    update public.leads set ai_rerun = true where id = p_lead;   -- tell the holder to run again
    return false;
  end if;
  return true;
end $$;

-- Releases the lock; returns true if another message arrived meanwhile (caller should run once more).
create or replace function public.release_lead_turn(p_lead uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare again boolean;
begin
  select ai_rerun into again from public.leads where id = p_lead for update;
  update public.leads set ai_lock_until = null, ai_rerun = false where id = p_lead;
  return coalesce(again, false);
end $$;

revoke execute on function public.rate_limit_hit(text, integer, integer) from public, anon, authenticated;
revoke execute on function public.claim_lead_turn(uuid, integer) from public, anon, authenticated;
revoke execute on function public.release_lead_turn(uuid) from public, anon, authenticated;
grant execute on function public.rate_limit_hit(text, integer, integer) to service_role;
grant execute on function public.claim_lead_turn(uuid, integer) to service_role;
grant execute on function public.release_lead_turn(uuid) to service_role;

-- Internal helpers are not part of the public API.
revoke execute on function public.touch_updated_at() from public, anon, authenticated;
revoke execute on function public.create_business(text) from public, anon;
grant execute on function public.create_business(text) to authenticated;

-- ═════════════════════════════ 20261126000100_recovery_sweep.sql ═════════════════════════════
-- Recovery sweep: conversations left unanswered by a crashed or timed-out request.
create or replace function public.leads_needing_ai(p_limit integer default 20)
returns table (id uuid, ai_retry_count smallint, needs_first_reply boolean)
language sql stable security definer set search_path = public as $$
  select l.id, l.ai_retry_count, (l.last_outbound_at is null) as needs_first_reply
  from public.leads l
  where l.ai_paused = false
    and l.status in ('new', 'contacted', 'engaged', 'qualified')
    and l.ai_retry_count < 3
    and (l.ai_lock_until is null or l.ai_lock_until < now())
    and (
      (l.last_outbound_at is null and l.created_at between now() - interval '24 hours' and now() - interval '2 minutes')
      or (l.last_inbound_at > coalesce(l.last_outbound_at, '-infinity'::timestamptz)
          and l.last_inbound_at between now() - interval '24 hours' and now() - interval '2 minutes')
    )
  order by coalesce(l.last_inbound_at, l.created_at)
  limit greatest(1, least(p_limit, 100));
$$;
revoke execute on function public.leads_needing_ai(integer) from public, anon, authenticated;
grant execute on function public.leads_needing_ai(integer) to service_role;

-- ═════════════════════════════ 20261127000000_redteam_fixes.sql ═════════════════════════════
-- Red-team fixes.
-- Finding: authenticated users could write business settings straight through the REST API, bypassing all
-- server-side validation (e.g. a 200 KB description sent to the AI on every turn, javascript: links, bad time zones).
-- Fix 1: no direct writes at all — settings are written by the server after validation (service role).
-- Fix 2: database constraints as defense in depth, so even a server bug can't store invalid data.
-- Constraints are added NOT VALID (safe on a live table: enforced for new writes without a full-table lock);
-- validate them later with ALTER TABLE ... VALIDATE CONSTRAINT once existing rows are checked.

revoke update on public.businesses from authenticated;
drop policy if exists "members update business" on public.businesses;

create or replace function public.is_valid_timezone(tz text) returns boolean
language sql stable set search_path = '' as $$
  select exists (select 1 from pg_catalog.pg_timezone_names where name = tz);
$$;

create or replace function public.validate_business() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not public.is_valid_timezone(new.timezone) then
    raise exception 'invalid timezone' using errcode = '23514';
  end if;
  return new;
end $$;
drop trigger if exists businesses_validate on public.businesses;
create trigger businesses_validate before insert or update of timezone on public.businesses
  for each row execute function public.validate_business();

alter table public.businesses
  add constraint biz_name_len check (char_length(name) between 2 and 100) not valid,
  add constraint biz_description_len check (char_length(description) <= 1500) not valid,
  add constraint biz_custom_len check (char_length(custom_instructions) <= 2000) not valid,
  add constraint biz_tone check (tone in ('friendly', 'professional', 'casual')) not valid,
  add constraint biz_currency check (currency in ('EUR', 'GBP', 'USD', 'CAD', 'AUD')) not valid,
  add constraint biz_services_shape check (jsonb_typeof(services) = 'array' and jsonb_array_length(services) <= 40 and octet_length(services::text) <= 20000) not valid,
  add constraint biz_faqs_shape check (jsonb_typeof(faqs) = 'array' and jsonb_array_length(faqs) <= 40 and octet_length(faqs::text) <= 60000) not valid,
  add constraint biz_hours_shape check (jsonb_typeof(opening_hours) = 'object' and octet_length(opening_hours::text) <= 2000) not valid,
  add constraint biz_areas_len check (cardinality(service_areas) <= 60) not valid,
  add constraint biz_urls check (
    (website is null or (website ~* '^https?://' and char_length(website) <= 500)) and
    (booking_link is null or (booking_link ~* '^https?://' and char_length(booking_link) <= 500))) not valid,
  add constraint biz_phones check (
    (notify_phone is null or notify_phone ~ '^\+[1-9][0-9]{6,14}$') and
    (sms_number is null or sms_number ~ '^\+[1-9][0-9]{6,14}$')) not valid,
  add constraint biz_followups check (
    cardinality(follow_up_delays_hours) <= 8 and 1 <= all(follow_up_delays_hours) and 720 >= all(follow_up_delays_hours)) not valid,
  add constraint biz_quiet_hours check (quiet_hours_start between 0 and 23 and quiet_hours_end between 0 and 23) not valid,
  add constraint biz_job_value check (average_job_value between 0 and 1000000) not valid;

alter table public.leads
  add constraint lead_name_len check (char_length(name) between 1 and 100) not valid,
  add constraint lead_text_len check (
    char_length(coalesce(initial_message, '')) <= 2000 and char_length(coalesce(service_requested, '')) <= 120 and
    char_length(coalesce(location, '')) <= 120 and char_length(coalesce(ai_summary, '')) <= 1000) not valid,
  add constraint lead_details_size check (jsonb_typeof(details) = 'object' and octet_length(details::text) <= 8000) not valid;

alter table public.messages add constraint msg_body_len check (char_length(body) <= 5000) not valid;

-- create_business: bound the name (it's callable by any signed-in user).
create or replace function public.create_business(p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare bid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_name is null or char_length(trim(p_name)) not between 2 and 100 then
    raise exception 'invalid business name' using errcode = '22023';
  end if;
  select business_id into bid from public.business_members where user_id = auth.uid() limit 1;
  if bid is not null then return bid; end if;
  insert into public.businesses (name, notify_email)
    values (trim(p_name), (select email from auth.users where id = auth.uid()))
    returning id into bid;
  insert into public.business_members (business_id, user_id, role) values (bid, auth.uid(), 'owner');
  return bid;
end $$;
revoke execute on function public.create_business(text) from public, anon;
grant execute on function public.create_business(text) to authenticated;
revoke execute on function public.is_valid_timezone(text) from public, anon;
revoke execute on function public.validate_business() from public, anon, authenticated;

-- ═════════════════════════════ 20261128000000_privacy_consent_compliance.sql ═════════════════════════════
-- Privacy-by-design, messaging consent, AI controls, audit trail.
-- Additive. Existing businesses keep their current behaviour (ai_mode = 'auto'); NEW businesses start in 'review'.

-- ─────────────── Business-level controls ───────────────
alter table public.businesses
  add column if not exists ai_mode text not null default 'review',
  add column if not exists ai_mode_acknowledged_at timestamptz,
  add column if not exists ai_mode_acknowledged_by uuid references auth.users(id) on delete set null,
  add column if not exists retention_days integer default 365,
  add column if not exists max_ai_messages_per_lead_per_day smallint not null default 10;
update public.businesses set ai_mode = 'auto' where ai_mode = 'review' and created_at < now(); -- preserve existing behaviour
alter table public.businesses
  add constraint biz_ai_mode check (ai_mode in ('auto', 'review', 'off')),
  add constraint biz_retention check (retention_days is null or retention_days between 30 and 3650),
  add constraint biz_lead_msg_cap check (max_ai_messages_per_lead_per_day between 1 and 25);

-- ─────────────── Per-lead consent (per channel) ───────────────
alter table public.leads
  add column if not exists sms_consent text not null default 'none',
  add column if not exists sms_consent_at timestamptz,
  add column if not exists sms_consent_source text,
  add column if not exists do_not_contact boolean not null default false;
alter table public.leads add constraint lead_sms_consent check (sms_consent in ('none', 'granted', 'revoked'));
-- Pre-existing SMS leads: mark as legacy so they are visible for review (no consent evidence exists for them).
update public.leads set sms_consent = 'granted', sms_consent_source = 'legacy_pre_consent_tracking', sms_consent_at = created_at
  where channel = 'sms' and status <> 'opted_out';
update public.leads set sms_consent = 'revoked', sms_consent_source = 'keyword_stop' where status = 'opted_out';

-- Append-only consent ledger: the record that demonstrates what each person agreed to, when, and how.
create table public.consent_events (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  lead_id uuid references public.leads(id) on delete set null,   -- proof survives lead deletion (pseudonymised)
  phone_hash text,                                               -- sha256(business_id:phone), no raw number
  channel text not null check (channel in ('sms', 'email')),
  action text not null check (action in ('granted', 'revoked', 'reinstated')),
  basis text not null check (basis in ('inbound_message', 'web_form_checkbox', 'owner_attestation', 'keyword_stop',
                                        'keyword_start', 'ai_detected_opt_out', 'owner_marked_do_not_contact', 'api')),
  evidence jsonb not null default '{}'::jsonb,                   -- consent wording, form URL, actor user id, ip hash
  created_at timestamptz not null default now()
);
create index on public.consent_events (business_id, created_at desc);
create index on public.consent_events (lead_id);

-- Suppression list: numbers that must never be messaged again, kept even after a lead is deleted.
create table public.suppression_list (
  business_id uuid not null references public.businesses(id) on delete cascade,
  phone_hash text not null,
  channel text not null default 'sms',
  reason text not null,
  created_at timestamptz not null default now(),
  primary key (business_id, phone_hash, channel)
);

-- Audit trail of important automated and human actions.
create table public.audit_log (
  id uuid primary key default gen_random_uuid(),
  business_id uuid references public.businesses(id) on delete cascade,
  actor_type text not null check (actor_type in ('user', 'ai', 'system')),
  actor_user_id uuid references auth.users(id) on delete set null,
  action text not null,
  target_type text,
  target_id uuid,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index on public.audit_log (business_id, created_at desc);

-- Acceptance of legal documents (versioned).
create table public.agreements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  business_id uuid references public.businesses(id) on delete cascade,
  document text not null check (document in ('terms', 'privacy', 'business_responsibilities')),
  version text not null,
  accepted_at timestamptz not null default now(),
  ip_hash text,
  user_agent text
);
create index on public.agreements (user_id, document);

-- Append-only: ledger and audit rows can be deleted (retention/erasure/account deletion) but never edited.
create or replace function public.forbid_update() returns trigger language plpgsql set search_path = '' as $$
begin raise exception '% is append-only', tg_table_name using errcode = '42501'; end $$;
create trigger consent_events_append_only before update on public.consent_events for each row execute function public.forbid_update();
create trigger audit_log_append_only before update on public.audit_log for each row execute function public.forbid_update();
create trigger agreements_append_only before update on public.agreements for each row execute function public.forbid_update();

-- ─────────────── Messages: review workflow & provenance ───────────────
alter table public.messages
  add column if not exists approved_by uuid references auth.users(id) on delete set null,
  add column if not exists approved_at timestamptz,
  add column if not exists original_body text;            -- AI draft text if the owner edited it before sending
alter table public.messages add constraint msg_status check (status in ('draft', 'discarded', 'queued', 'sent', 'delivered', 'failed', 'received'));

-- DATABASE-LEVEL GUARANTEE: no outbound SMS can be recorded (and therefore sent — we record before sending)
-- for a lead without SMS consent, marked do-not-contact, opted out, or on the suppression list.
create or replace function public.enforce_sms_consent() returns trigger language plpgsql security definer set search_path = '' as $$
declare l record;
begin
  if new.direction = 'outbound' and new.channel = 'sms' and new.status in ('queued', 'sent', 'delivered') then
    select status, sms_consent, do_not_contact, phone, business_id into l from public.leads where id = new.lead_id;
    if l.status = 'opted_out' or l.do_not_contact or l.sms_consent <> 'granted' then
      raise exception 'sms blocked: no consent or opted out' using errcode = '42501';
    end if;
    if l.phone is not null and exists (select 1 from public.suppression_list s where s.business_id = l.business_id
        and s.channel = 'sms' and s.phone_hash = encode(extensions.digest(l.business_id::text || ':' || l.phone, 'sha256'), 'hex')) then
      raise exception 'sms blocked: number is suppressed' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
create trigger messages_enforce_sms_consent before insert or update of status on public.messages
  for each row execute function public.enforce_sms_consent();

-- ─────────────── Retention ───────────────
-- Deletes leads (and by cascade their messages, follow-ups, events, alerts) older than each business's retention period.
-- Consent/suppression records are kept (pseudonymised) so opt-outs keep being honoured — see docs/legal/LEGAL_RISK_REGISTER.md.
create or replace function public.purge_expired_data()
returns table (business_id uuid, leads_deleted integer)
language plpgsql security definer set search_path = '' as $$
declare b record; n integer;
begin
  for b in select id, retention_days from public.businesses where retention_days is not null loop
    delete from public.leads l where l.business_id = b.id
      and coalesce(l.last_message_at, l.created_at) < now() - make_interval(days => b.retention_days);
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.audit_log (business_id, actor_type, action, details)
        values (b.id, 'system', 'retention.purged', jsonb_build_object('leads_deleted', n, 'retention_days', b.retention_days));
      business_id := b.id; leads_deleted := n; return next;
    end if;
  end loop;
  delete from public.notifications where created_at < now() - interval '180 days';
end $$;

-- ─────────────── RLS: members can READ their own business's records; all writes are server-side ───────────────
alter table public.consent_events enable row level security;
alter table public.suppression_list enable row level security;
alter table public.audit_log enable row level security;
alter table public.agreements enable row level security;
create policy "members read consent" on public.consent_events for select to authenticated using (public.is_member(business_id));
create policy "members read suppression" on public.suppression_list for select to authenticated using (public.is_member(business_id));
create policy "members read audit" on public.audit_log for select to authenticated using (public.is_member(business_id));
create policy "read own agreements" on public.agreements for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete, truncate on public.consent_events, public.suppression_list, public.audit_log, public.agreements from authenticated, anon;

revoke execute on function public.purge_expired_data() from public, anon, authenticated;
revoke execute on function public.enforce_sms_consent() from public, anon, authenticated;
revoke execute on function public.forbid_update() from public, anon, authenticated;
grant execute on function public.purge_expired_data() to service_role;

-- ═════════════════════════════ 20261128000100_security_posture.sql ═════════════════════════════
-- Read-only posture check for the internal risk dashboard (service role only).
create or replace function public.security_posture()
returns table (tables_total integer, tables_without_rls text[], legacy_consent_leads integer,
               auto_mode_without_ack integer, last_retention_purge timestamptz)
language sql stable security definer set search_path = '' as $$
  select
    (select count(*)::int from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind = 'r'),
    (select coalesce(array_agg(c.relname::text), '{}') from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity),
    (select count(*)::int from public.leads where sms_consent_source = 'legacy_pre_consent_tracking'),
    (select count(*)::int from public.businesses where ai_mode = 'auto' and ai_mode_acknowledged_at is null),
    (select max(created_at) from public.audit_log where action = 'retention.purged');
$$;
revoke execute on function public.security_posture() from public, anon, authenticated;
grant execute on function public.security_posture() to service_role;

-- ═════════════════════════════ 20261128000200_append_only_allows_erasure.sql ═════════════════════════════
-- Fix: the append-only trigger also blocked the ON DELETE SET NULL that runs when a lead (or user) is deleted,
-- so erasing a lead with consent history failed. Records stay immutable; the ONLY permitted change is
-- unlinking a deleted lead/user (pseudonymisation), with every other column unchanged.
create or replace function public.forbid_update() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_table_name = 'consent_events' and new.lead_id is null
     and (to_jsonb(new) - 'lead_id') = (to_jsonb(old) - 'lead_id') then
    return new;
  end if;
  if tg_table_name = 'audit_log' and new.actor_user_id is null
     and (to_jsonb(new) - 'actor_user_id') = (to_jsonb(old) - 'actor_user_id') then
    return new;
  end if;
  raise exception '% is append-only', tg_table_name using errcode = '42501';
end $$;

-- ═════════════════════════════ 20261128000300_sticky_opt_out.sql ═════════════════════════════
-- Race-condition fix (found by the compliance test suite): a request holding a stale copy of a lead could
-- overwrite status 'opted_out' (e.g. with 'engaged' or 'qualified') when a STOP arrived at the same moment.
-- Texts were still blocked (consent is checked separately), but the opt-out state must never be lost.
-- Rule: an opted-out lead stays opted out unless SMS consent has been explicitly re-granted (person texted START).
create or replace function public.keep_opt_out() returns trigger language plpgsql set search_path = '' as $$
begin
  if old.status = 'opted_out' and new.status is distinct from 'opted_out' and new.sms_consent <> 'granted' then
    new.status := 'opted_out';
  end if;
  if old.sms_consent = 'revoked' and new.sms_consent = 'granted'
     and coalesce(new.sms_consent_source, '') not in ('keyword_start') then
    new.sms_consent := 'revoked';     -- only the person (START) can undo their own opt-out
    new.sms_consent_source := old.sms_consent_source;
    new.sms_consent_at := old.sms_consent_at;
  end if;
  if old.do_not_contact and not new.do_not_contact then
    new.do_not_contact := true;       -- do-not-contact is permanent
  end if;
  return new;
end $$;
create trigger leads_keep_opt_out before update on public.leads for each row execute function public.keep_opt_out();
revoke execute on function public.keep_opt_out() from public, anon, authenticated;

-- ═════════════════════════════ 20261128000400_fix_append_only_check.sql ═════════════════════════════
-- PL/pgSQL does not short-circuit AND, so referencing NEW.actor_user_id on consent_events (or NEW.lead_id on
-- audit_log) raised "record has no field". Use per-table branches.
create or replace function public.forbid_update() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_table_name = 'consent_events' then
    if (to_jsonb(new) ->> 'lead_id') is null and (to_jsonb(new) - 'lead_id') = (to_jsonb(old) - 'lead_id') then return new; end if;
  elsif tg_table_name = 'audit_log' then
    if (to_jsonb(new) ->> 'actor_user_id') is null and (to_jsonb(new) - 'actor_user_id') = (to_jsonb(old) - 'actor_user_id') then return new; end if;
  end if;
  raise exception '% is append-only', tg_table_name using errcode = '42501';
end $$;

-- ═════════════════════════════ 20261128000500_explicit_grants.sql ═════════════════════════════
-- Make every privilege explicit instead of relying on Supabase's platform default grants.
-- (Found by testing the combined schema on a fresh database: without those defaults, users could read
--  nothing and the service role could do nothing. Explicit grants make the schema self-contained and auditable.)

grant usage on schema public to anon, authenticated, service_role;

-- Server role: full access (it is only ever used server-side, after explicit authorization checks).
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- Logged-in users: READ ONLY on customer data (RLS limits rows to their own business).
grant select on public.businesses, public.business_members, public.leads, public.messages, public.follow_ups,
  public.lead_events, public.notifications, public.consent_events, public.suppression_list, public.audit_log,
  public.agreements to authenticated;
-- …plus exactly one write: marking their own alerts as read.
grant update (read_at) on public.notifications to authenticated;
grant execute on function public.create_business(text) to authenticated;
grant execute on function public.is_member(uuid) to authenticated;

-- Least privilege: privileges no app role needs.
revoke references, trigger, truncate on all tables in schema public from anon, authenticated;
revoke all on public.webhook_events, public.rate_limits from anon, authenticated;
revoke all on all tables in schema public from anon;

-- Internal helper used only by the businesses validation trigger (server writes only).
revoke execute on function public.is_valid_timezone(text) from authenticated;

-- ═════════════════════════════ 20261128000600_followup_claim_time.sql ═════════════════════════════
-- Reliability: record WHEN a follow-up was claimed, so a claim left behind by a killed function
-- (e.g. platform timeout mid-run) can be detected and released instead of staying "processing" forever.
alter table public.follow_ups add column if not exists claimed_at timestamptz;
create index if not exists follow_ups_processing on public.follow_ups (status, claimed_at) where status = 'processing';

